    [Theory]
    [MemberData(nameof(SourceCases))]
    public void Owned_generation_WaterCheck_matches_actual_source(
        string profile, string encoded, string before, string after, string randomState,
        int nextRandom, bool waterDeath, bool lavaDeath)
    {
        _ = profile;
        var workspace = new Workspace(80, 80);
        workspace.TrySetLayers(40, 60);
        workspace.SetVanillaBootstrapState(BootstrapPass1458.Run(new RandomAdapter(1), 4200, false, TerraRuntime.World.VanillaSpecialWorldSeed1458.None));
        foreach (string member in encoded.Split(';'))
        {
            int[] a = member.Split(',').Select(int.Parse).ToArray();
            var t = new WorldTile
            {
                Type = (ushort)a[3],
                Wall = (ushort)a[4],
                FrameX = (short)a[5],
                FrameY = (short)a[6],
                LiquidAmount = (byte)a[7],
                LiquidKind = (WorldLiquidKind)a[8],
                TileColor = (byte)a[11],
                WallColor = (byte)a[12],
                Flags = a[2] != 0 ? WorldTileFlags.Active : WorldTileFlags.None
            };
            Assert.True(t.TrySetSourceShape(a[9] != 0, (byte)a[10]));
            WorldTileFlags[] flags = [WorldTileFlags.WireRed, WorldTileFlags.WireBlue, WorldTileFlags.WireGreen,
                WorldTileFlags.WireYellow, WorldTileFlags.Actuator, WorldTileFlags.Inactive, WorldTileFlags.InvisibleBlock,
                WorldTileFlags.FullbrightBlock, WorldTileFlags.InvisibleWall, WorldTileFlags.FullbrightWall];
            for (int n = 0; n < flags.Length; n++) if (a[13 + n] != 0) t.Flags |= flags[n];
            workspace.TileStore.Set(a[0], a[1], in t);
        }
        Assert.Equal(before, FullState(workspace));
        WorldTile target = workspace.TileStore.Get(40, 40);
        Assert.True(VanillaTileObjectLiquidDeath1458.TryGet(in target, out bool water, out bool lava));
        Assert.Equal(waterDeath, water);
        Assert.Equal(lavaDeath, lava);
        var random = new RandomAdapter(1458);
        var framing = new GenerationTileFraming1458(workspace.TileStore, random, workspace, useWorldGenerationSolidity: true);
        VanillaWaterCheckDiagnostic1458 diagnostic = framing.WaterCheckLiquidsDuringGeneration();
        Assert.True(diagnostic.IsApplied, diagnostic.ToString());
        Assert.Equal(after, FullState(workspace));
        Assert.Equal(randomState, random.Fingerprint());
        Assert.Equal(nextRandom, random.Next());
    }

    private static string FullState(Workspace workspace)
    {
        var b = new StringBuilder();
        for (int x = 0; x < workspace.WidthTiles; x++)
            for (int y = 0; y < workspace.HeightTiles; y++)
            {
                WorldTile t = workspace.TileStore.Get(x, y);
                b.Append(t.IsActive ? 1 : 0).Append(',').Append(t.Type).Append(',').Append(t.Wall).Append(',')
                    .Append(t.FrameX).Append(',').Append(t.FrameY).Append(',').Append(t.LiquidAmount).Append(',')
                    .Append((int)t.LiquidKind).Append(',').Append(t.IsHalfBrick ? 1 : 0).Append(',').Append(t.SourceSlope).Append(',')
                    .Append(t.TileColor).Append(',').Append(t.WallColor);
                WorldTileFlags[] flags = [WorldTileFlags.WireRed, WorldTileFlags.WireBlue, WorldTileFlags.WireGreen,
                WorldTileFlags.WireYellow, WorldTileFlags.Actuator, WorldTileFlags.Inactive, WorldTileFlags.InvisibleBlock,
                WorldTileFlags.FullbrightBlock, WorldTileFlags.InvisibleWall, WorldTileFlags.FullbrightWall];
                foreach (WorldTileFlags flag in flags) b.Append(',').Append((t.Flags & flag) != 0 ? 1 : 0);
                b.Append(';');
            }
        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(b.ToString())));
    }


    private sealed class RandomAdapter(int seed) : IWorldGenerationVanillaRandom
    {
        private readonly VanillaUnifiedRandom1458 random = new(seed);
        public string Fingerprint()
        {
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            var cursor = typeof(VanillaUnifiedRandom1458).GetField("inext", flags)!.GetValue(random);
            var slots = (int[])typeof(VanillaUnifiedRandom1458).GetField("seedArray", flags)!.GetValue(random)!;
            return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(cursor + ";" + string.Join(",", slots))));
        }
        public int Next() => random.Next();
        public int Next(int maxValue) => random.Next(maxValue);
        public int Next(int minValue, int maxValue) => random.Next(minValue, maxValue);
        public double NextDouble() => random.NextDouble();
        public void NextBytes(byte[] buffer) => random.NextBytes(buffer);
    }
